package com.luvly.luvly_app.ar

import java.io.File
import org.junit.Assert.*
import org.junit.Assume.assumeTrue
import org.junit.Test

/** Optional local QA. No user landmark data is committed as a project fixture.
 * Desktop inference of a screen recording is a diagnostic, not device accuracy.
 * Supply LUVLY_SCAN_REPLAY to a local TSV generated by the review script. */
class BodyScanReplayTest {
    @Test fun suppliedRecordingReachesAStableResultWithoutBypassingChecks(){
        val supplied=System.getenv("LUVLY_SCAN_REPLAY")
        assumeTrue("No private replay supplied",supplied!=null && File(supplied).isFile)
        fun people(raw: String): List<List<BodyProportionScan.Joint>> = if(raw.isEmpty())emptyList() else raw.split('/').map{person->person.split(';').map{point->
            val v=point.split(',').map{it.toDouble()};BodyProportionScan.Joint(v[0],v[1],v[2],v[3])
        }}
        for(minimumInterval in listOf(0L,200L)){
        val scan=BodyProportionScan();val reasons=mutableMapOf<String,Int>()
        var successes=0;var maximum=0;var previousTime=-10000L
        File(supplied!!).forEachLine{line->
            val cols=line.split('\t');val time=cols[0].toLong()
            if(time-previousTime<minimumInterval)return@forEachLine
            previousTime=time
            val u=scan.add(people(cols[1]),people(cols[2]),480,640,time,120.0)
            if(System.getenv("LUVLY_SCAN_REPLAY_VERBOSE")=="1")println("Replay time=$time accepted=${u.count} state=${u.guidance}")
            reasons[u.guidance]=(reasons[u.guidance]?:0)+1;maximum=maxOf(maximum,u.count)
            if(u.result!=null){successes++;assertTrue(u.result.sampleCount>=15);assertTrue(u.result.durationMs>=3000);assertTrue(u.result.relativeSpread<=.035);scan.reset()}
        }
        println("Local diagnostic replay: minimumInterval=$minimumInterval results=$successes maximumValidSamples=$maximum states=$reasons")
        assertTrue("Replay should contain a stable supported window; inspect state counts",successes>0)
        }
    }
}
